from itertools import combinations

# For each k, find which 6 values from {k,...,k+13} sum to 666
# and which 6 values sum to 666 (rows and cols must both sum to 666)
# The rows use 6 values, cols use 6 values, diags use 2 values
# All 14 are distinct and cover {k,...,k+13}

# So we need to partition {k,...,k+13} into three groups:
# R (6 values for rows), C (6 values for cols), D (2 values for diags)
# sum(R) = 666, sum(C) = 666, sum(D) = 14k+91 - 1332 = 14k - 1241

for k in range(101, 109):
    vals = list(range(k, k+14))
    total = sum(vals)
    diag_sum_needed = total - 666 - 666  # d1 + d2
    print(f"k={k}: vals={vals[0]}..{vals[-1]}, sum={total}, diag_sum_needed={diag_sum_needed}")

    # Find pairs from vals that sum to diag_sum_needed
    valid_pairs = []
    for i in range(14):
        for j in range(i+1, 14):
            if vals[i] + vals[j] == diag_sum_needed:
                valid_pairs.append((vals[i], vals[j]))

    if valid_pairs:
        print(f"  Valid diagonal pairs: {valid_pairs}")
        # For each pair, check if remaining 12 can be split into two groups of 6 each summing to 666
        for d1, d2 in valid_pairs:
            remaining = [v for v in vals if v != d1 and v != d2]
            # Find 6 from remaining summing to 666
            found = False
            for combo in combinations(remaining, 6):
                if sum(combo) == 666:
                    other = [v for v in remaining if v not in combo]
                    if sum(other) == 666:
                        print(f"    Diags={d1},{d2}, Rows={sorted(combo)}, Cols={sorted(other)}")
                        found = True
                        break
            if not found:
                print(f"    Diags={d1},{d2}: No valid row/col split")

